const dicts: Record<Locale, Dict> = { es, en, pt };

interface I18n {
  locale: Locale;
  setLocale: (l: Locale) => void;
  t: (key: string, vars?: Record<string, string | number>) => string;
  n: (value: number) => string;
  money: (usd: number) => string;
  date: (iso: string) => string;
}

const Ctx = createContext<I18n | null>(null);

export function I18nProvider({ children }: { children: ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>("es");

  useEffect(() => {
    const saved = localStorage.getItem("lul-locale") as Locale | null;
    const detected = navigator.language.slice(0, 2) as Locale;
    const next = saved && dicts[saved] ? saved : dicts[detected] ? detected : "es";
    setLocaleState(next);
  }, []);

  useEffect(() => { document.documentElement.lang = locale; }, [locale]);

  const setLocale = useCallback((l: Locale) => { setLocaleState(l); localStorage.setItem("lul-locale", l); }, []);

  const value = useMemo<I18n>(() => ({
    locale,
    setLocale,
    t: (key, vars) => {
      let s = dicts[locale][key] ?? es[key] ?? key;
      if (vars) for (const [k, v] of Object.entries(vars)) s = s.replaceAll(`{${k}}`, String(v));
      return s;
    },
    n: (v) => v.toLocaleString(intlLocale[locale]),
    money: (usd) => new Intl.NumberFormat(intlLocale[locale], { style: "currency", currency: "USD" }).format(usd),
    date: (iso) => new Intl.DateTimeFormat(intlLocale[locale], { dateStyle: "medium", timeStyle: "short" }).format(new Date(iso)),
  }), [locale, setLocale]);

  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

export function useI18n() {
  const ctx = useContext(Ctx);
  if (!ctx) throw new Error("useI18n must be used inside I18nProvider");
  return ctx;
}
